using System;using System.IO;using System.Drawing;using System.Windows.Forms;using System.Collections.Generic;using System.Diagnostics;using System.Web.Script.Serialization;
public class PairFixture {
 static string dir;static Form main,alpha;static TextBox result,draft,other;static int lhs,n;static bool entering;static string op="";static List<string> buttons=new List<string>();static JavaScriptSerializer json=new JavaScriptSerializer();
 static void Save(){string p=Path.Combine(dir,"state.json"),tmp=p+".tmp";File.WriteAllText(tmp,json.Serialize(new{display=result.Text,draft=draft.Text,Alpha=other.Text,buttons=buttons,pid=Process.GetCurrentProcess().Id,window=main.Handle.ToInt64(),alpha_window=alpha.Handle.ToInt64(),screen=new[]{SystemInformation.VirtualScreen.Width,SystemInformation.VirtualScreen.Height,1}}));if(File.Exists(p))File.Replace(tmp,p,null);else File.Move(tmp,p);}
 static void Press(string key){buttons.Add(key);int digit;if(int.TryParse(key,out digit)){n=entering?n*10+digit:digit;entering=true;result.Text=n.ToString();}else if(key=="×"){lhs=n;op=key;entering=false;result.Text=lhs+" ×";}else if(key=="="){n=op=="×"?lhs*n:n;result.Text=n.ToString();entering=false;}else{lhs=0;n=0;op="";entering=false;result.Text="0";}Save();}
 [STAThread]public static void Main(string[] args){dir=args[0];Directory.CreateDirectory(dir);Application.EnableVisualStyles();main=new Form{Text="Paired task fixture",ClientSize=new Size(560,420),StartPosition=FormStartPosition.Manual,Location=new Point(30,30)};alpha=new Form{Text="Alpha document",ClientSize=new Size(300,200),StartPosition=FormStartPosition.Manual,Location=new Point(650,60)};result=new TextBox{Text="0",AccessibleName="Result",Name="result",Bounds=new Rectangle(20,20,500,40)};draft=new TextBox{Text="seed",AccessibleName="Draft",Name="draft",Multiline=true,Bounds=new Rectangle(20,200,490,100)};other=new TextBox{Text="alpha",AccessibleName="Alpha",Name="alpha",Bounds=new Rectangle(20,50,240,40)};main.Controls.Add(result);main.Controls.Add(draft);alpha.Controls.Add(other);int i=0;foreach(string label in new[]{"6","7","×","=","Clear"}){string key=label;var b=new Button{Text=key,AccessibleName=key,Name="button-"+key,Bounds=new Rectangle(20+i++*100,100,90,40)};b.Click+=(o,e)=>Press(key);main.Controls.Add(b);}var timer=new Timer{Interval=50};timer.Tick+=(o,e)=>Save();main.Shown+=(o,e)=>{alpha.Show();main.Activate();Save();timer.Start();};Application.Run(main);}
}
